import sys, json, random
sys.path.insert(0, '/app/tmp/t')
from harness import *

random.seed(99)

URI_PARTS = ["sip", "sips", "SIP", "Sips", "tel", "T EL", "http", "sipx"]
USER_PARTS = ["alice", "Alice", "a", "%61lice", "%6 1", "%", "%zz", "%41", "a b", "a+b", "a;b", "a:b", "a,b", "a(b)", "a*b", "a~b", "a!b", "a'b", "a.b", "a_b", "a-b", "", "x"*64, "x"*65, "%25", "%40", "%20"]
HOST_PARTS = ["lab.test", "LAB.TEST", "lab", "a.b", "a-b.c-d", "-a.b", "a-.b", "a..b", ".a.b", "a.b.", "1.2.3.4", "a_b.test", "x"*63+".b", "x"*64+".b", "a."+"x"*63, "a.test:5060", "a.test:0", "a.test:65536", "a.test:99999", "a.test:", "a.test:0a"]
PORTS = ["", ":5060", ":0", ":65535", ":65536", ":005060", ":1", ":00001", ":123456"]
TAGS = ["t", "T", "", "x"*32, "x"*33, "a b", "a;b", "%41", "tag"]
DISPLAYS = ["", "Alice", "Alice QA", '"Alice"', '"A,B"', '"A\\"B"', '"A<B"', '"AB\\"', '"AB"x', "A(B)", "A@B", "A<B>", "A.B-C"]
ADDR_WRAPS = ["{u}", "<{u}>", "{d} <{u}>", "{d}<{u}>", '"{d}" <{u}>', "{d} <{u}> extra", "< {u} >", "<{u}>x", "{u} x"]

def rand_uri():
    s = random.choice(URI_PARTS) + ":" + random.choice(USER_PARTS)
    if random.random() < 0.8:
        s += "@" + random.choice(HOST_PARTS)
    if random.random() < 0.3:
        s += random.choice(PORTS)
    return s

def rand_addr():
    u = rand_uri()
    d = random.choice(DISPLAYS)
    w = random.choice(ADDR_WRAPS)
    return w.format(u=u, d=d)

def rand_from():
    a = rand_addr()
    t = random.choice(TAGS)
    fmt = random.choice(["{a};tag={t}", "{a} ; tag = {t}", "{a};TAG={t}", "{a}", "{a};tag={t};x=1", "{a};tag=", "{a} ;tag={t}"])
    return fmt.format(a=a, t=t)

def rand_hdr_line():
    r = random.random()
    if r < 0.25:
        return ("From", rand_from())
    if r < 0.45:
        return ("To", rand_addr())
    if r < 0.55:
        return (random.choice(["P-Asserted-Identity", "P-Preferred-Identity"]),
                random.choice([rand_addr(), rand_addr() + "," + rand_addr(), "," + rand_addr(), rand_addr() + ",", "", "  "]))
    if r < 0.65:
        return ("Privacy", random.choice(["id", "none", "ID", "id;id", "id;none", "", "id;", "x", " id "]))
    if r < 0.75:
        return ("Call-ID", random.choice(["demo", "a"*64, "a"*65, "de mo", "a:b", "", "a@b.c-d_e"]))
    if r < 0.85:
        return ("CSeq", random.choice(["7 MESSAGE", "7  MESSAGE", "0007 MESSAGE", "7 INVITE", "0 MESSAGE", "2147483647 MESSAGE", "2147483648 MESSAGE", "7", "7 MESSAGE x", "0000000007 MESSAGE", "00000000007 MESSAGE"]))
    if r < 0.95:
        return ("Content-Length", random.choice(["0", "3", "003", "abc", "", "0000000003", "00000000003", " 3 "]))
    return (random.choice(["X-Junk", "Via", "Contact", "f", "t", "i", "l", "F", "authorization"]),
            random.choice(["v", "", "  ", "a b", "a,b"]))

def rand_request():
    method = random.choice(["MESSAGE", "MESSAGE", "INVITE"])
    uri = rand_uri()
    hdrs = []
    for _ in range(random.randint(3, 9)):
        hdrs.append(rand_hdr_line())
    body = bytes(random.randint(0, 255) for _ in range(random.randint(0, 4)))
    # keep CL consistent sometimes
    if random.random() < 0.6:
        hdrs = [h for h in hdrs if h[0].lower() not in ("content-length", "l")]
        hdrs.append(("Content-Length", str(len(body))))
    return mkreq(method=method, uri=uri, headers=hdrs, body=body)

cfg = base_config()
reasons = {}
bad = 0
for it in range(2500):
    evs = []
    for _ in range(random.randint(1, 4)):
        p = random.choice(["edge", "trunk"])
        evs.append(ev(random.randint(0, 3), p, None if p == "trunk" else random.choice(["alice", "bob", None]),
                      random.choice(["internal", "external"]), rand_request().hex()))
    evs.sort(key=lambda e: e["t"])
    rc, out, err = run(envelope(evs, cfg))
    if rc != 0:
        bad += 1
        print("BAD", rc, err[:400]); break
    d = json.loads(out)
    for r in d["results"]:
        if r["decision"] == "reject":
            assert r["reason"] in ("hex","syntax","headers","length","fields","auth","identity","conflict"), r
            reasons[r["reason"]] = reasons.get(r["reason"], 0) + 1
        else:
            assert set(r.keys()) == {"index","decision","first","account","identity","from","pai","method","target","call_id","cseq","tag","privacy","body_sha256"}, r
            assert r["privacy"] in ("id","none","absent")
            assert len(r["pai"]) <= 2
            assert len(r["body_sha256"]) == 64
print("bad:", bad, "reasons:", reasons)

# envelope fuzz: random JSON docs must never exit 0/1 unexpectedly
import string
def rand_json_val(depth=0):
    r = random.random()
    if depth > 3 or r < 0.3:
        return random.choice([1, 0, -1, True, False, None, "x", "", "edge", 1.5, 100, "a"*10])
    if r < 0.6:
        return [rand_json_val(depth+1) for _ in range(random.randint(0, 4))]
    d = {}
    for _ in range(random.randint(0, 5)):
        d[random.choice(["version","config","events","accounts","peers","ttl_ms","capacity","id","default","aliases","mode","t","peer","auth","egress","wire_hex","x"])] = rand_json_val(depth+1)
    return d
bad = 0
for it in range(600):
    doc = rand_json_val()
    rc, out, err = run(json.dumps(doc).encode())
    if rc not in (0, 2):
        bad += 1
        print("BAD RC", rc, err[:300], json.dumps(doc)[:200]); break
    if rc == 0:
        try:
            json.loads(out)
        except Exception as e:
            bad += 1; print("BAD OUT", out[:200]); break
print("envelope fuzz bad:", bad)
summary()
